sys_script_include.script:
var GRCOpsUtils = Class.create();
GRCOpsUtils.prototype = {
    initialize: function() {},

	/**
	 * Function to fetch list of users who are a part of GRC Ops App
	 * return - query to fetch list of targeted users which will be queried on sys_user table
	 */
    fetchGRCOpsAppUsers: function() {
        var gr = new GlideRecord("sys_user_grmember");
        gr.addEncodedQuery("group.nameSTARTSWITHGRC^user.last_nameNOT LIKE(Dev)");
        gr.query();
        var list = new Set();
        while (gr.next()) {
            list.add(gr.user.sys_id.toString());
        }
        var uniqueList = [];
        list.forEach(function(value) {
            uniqueList.push(value);
        });
        return 'sys_idIN' + uniqueList.join(',');
    },

	/**
	 * Function to return list of users to be used in Ref Qual pon Contributors Field
	 * in the Accelerators table.
	 * return - query to fetch list of targeted users based on Accelerator Type Selected. If Type = POD Based, returns list of POD members of the selected Employee, Else, returns list of users scoped under Ops App.
	 */
	queryBuildForContributors: function(current) {
		// var encodedQuery = '';
		// var resultQuery = 'sys_idIN';
		return 'sys_idIN' + current.resource;
	},

    type: 'GRCOpsUtils'
};
